"use client";

import { useId, useLayoutEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  type ChartCategory,
  type ChartFunnelStage,
  type ChartFunnelText,
  type ChartLabelKey,
  type ChartModel,
  chartFunnelLayout,
} from "@/components/ui/yayaw-table/utils/chart-model";
import { cn } from "@/lib/utils";

type Label = (
  key: ChartLabelKey,
  params?: Record<string, number | string>
) => string;

const percentOf = (part: number, whole: number) =>
  `${whole ? (part / whole) * 100 : 0}%`;

/** The funnel's width: measured, and followed as the container resizes. */
function useWidth() {
  const container = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  useLayoutEffect(() => {
    const element = container.current;
    if (!element) {
      return;
    }
    const measure = () => setWidth(Math.round(element.clientWidth));
    measure();
    if (typeof ResizeObserver === "undefined") {
      return;
    }
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  return { container, width };
}

function FunnelText({
  className,
  text,
}: {
  className: string;
  text: ChartFunnelText;
}) {
  return (
    <text className={className} textAnchor={text.anchor} x={text.x} y={text.y}>
      {text.text}
    </text>
  );
}

/** "Active: 3, 100% of first" and so on, for assistive technology. */
const stageSummary = (stage: ChartFunnelStage) =>
  [stage.valueText, stage.shareText, stage.conversionText]
    .filter(Boolean)
    .join(", ");

/**
 * The funnel: SVG shapes from the shared geometry (the Vue edition draws the
 * same), with a button over each stage that shows its records.
 */
export function FunnelChart({
  model,
  clickable,
  onGroup,
  label,
}: {
  model: ChartModel;
  clickable: boolean;
  onGroup: (category?: ChartCategory) => void;
  label: Label;
}) {
  const id = useId();
  const { container, width } = useWidth();
  const [active, setActive] = useState<string>();
  const layout = chartFunnelLayout(model.stages ?? [], width);
  return (
    <div
      className="relative w-full"
      data-chart-funnel={layout.orientation}
      ref={container}
    >
      <svg
        aria-describedby={`${id}-desc`}
        aria-labelledby={`${id}-title`}
        className="block h-auto w-full overflow-visible"
        height={layout.height}
        role="img"
        viewBox={`0 0 ${layout.width} ${layout.height}`}
        width={layout.width}
      >
        <title id={`${id}-title`}>{model.title}</title>
        <desc id={`${id}-desc`}>
          {layout.shapes
            .map(
              (shape) => `${shape.stage.label}: ${stageSummary(shape.stage)}`
            )
            .join("; ")}
        </desc>
        {layout.shapes.map((shape) => (
          <g data-funnel-stage={shape.stage.label} key={shape.stage.id}>
            <polygon
              className={cn(
                "transition-opacity",
                active && active !== shape.stage.id && "opacity-50"
              )}
              fill={shape.stage.color}
              points={shape.points}
            />
            <FunnelText
              className="fill-foreground font-medium text-xs"
              text={shape.name}
            />
            <FunnelText
              className="fill-foreground font-semibold text-xs tabular-nums"
              text={shape.value}
            />
            <FunnelText
              className="fill-muted-foreground text-[11px] tabular-nums"
              text={shape.share}
            />
            {shape.conversion ? (
              <FunnelText
                className="fill-muted-foreground text-[11px] tabular-nums"
                text={shape.conversion}
              />
            ) : null}
          </g>
        ))}
      </svg>
      {clickable
        ? layout.shapes
            .filter((shape) => !shape.stage.category.other)
            .map((shape) => (
              <button
                aria-label={label("showRecords", { group: shape.stage.label })}
                className="absolute cursor-pointer rounded-md outline-none hover:bg-foreground/5 focus-visible:ring-2 focus-visible:ring-ring"
                data-funnel-button
                key={shape.stage.id}
                onBlur={() => setActive(undefined)}
                onClick={() => onGroup(shape.stage.category)}
                onFocus={() => setActive(shape.stage.id)}
                onMouseEnter={() => setActive(shape.stage.id)}
                onMouseLeave={() => setActive(undefined)}
                style={{
                  left: percentOf(shape.box.x, layout.width),
                  top: percentOf(shape.box.y, layout.height),
                  width: percentOf(shape.box.width, layout.width),
                  height: percentOf(shape.box.height, layout.height),
                }}
                type="button"
              />
            ))
        : null}
    </div>
  );
}

/** The funnel's numbers as a table: stage, value, share of the first stage and conversion. */
export function FunnelDataTable({
  model,
  clickable,
  onGroup,
  label,
}: {
  model: ChartModel;
  clickable: boolean;
  onGroup: (category?: ChartCategory) => void;
  label: Label;
}) {
  const percent = (share: number | undefined) =>
    share === undefined ? "—" : model.formatShare(share);
  return (
    <div className="overflow-x-auto rounded-md border">
      <table className="w-full text-sm" data-chart-table>
        <caption className="sr-only">{model.title}</caption>
        <thead className="bg-muted/50 text-left text-muted-foreground">
          <tr>
            <th className="px-3 py-2 font-medium" scope="col">
              {label("stage")}
            </th>
            <th className="px-3 py-2 text-right font-medium" scope="col">
              {model.valueLabel}
            </th>
            <th className="px-3 py-2 text-right font-medium" scope="col">
              {label("shareOfFirst")}
            </th>
            <th className="px-3 py-2 text-right font-medium" scope="col">
              {label("conversion")}
            </th>
          </tr>
        </thead>
        <tbody>
          {(model.stages ?? []).map((stage) => (
            <tr className="border-t" key={stage.id}>
              <th className="px-3 py-1.5 text-left font-normal" scope="row">
                {clickable ? (
                  <Button
                    aria-label={label("showRecords", { group: stage.label })}
                    className="h-auto px-0 py-0 font-normal"
                    onClick={() => onGroup(stage.category)}
                    type="button"
                    variant="link"
                  >
                    {stage.label}
                  </Button>
                ) : (
                  stage.label
                )}
              </th>
              <td className="px-3 py-1.5 text-right tabular-nums">
                {stage.valueText}
              </td>
              <td className="px-3 py-1.5 text-right tabular-nums">
                {percent(stage.shareOfFirst)}
              </td>
              <td className="px-3 py-1.5 text-right tabular-nums">
                {percent(stage.conversion)}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

"use client";

import { lazy, Suspense } from "react";
import type {
  DisplayModeRenderContext,
  DisplayModeRenderer,
} from "@/components/ui/yayaw-table/types/display-mode-renderer";
import { chartLabel } from "@/components/ui/yayaw-table/utils/chart-model";
import { ChartSettings } from "./chart-settings";

// Recharts loads with the first chart shown, not with the table.
const LazyChartView = lazy(async () => ({
  default: (await import("./chart-view")).ChartView,
}));

function ChartViewLoader({ context }: { context: DisplayModeRenderContext }) {
  return (
    <Suspense
      fallback={
        <output className="block text-muted-foreground text-sm">
          {chartLabel("loading", context.locale, (key, fallback) =>
            context.translate(`chart.${key}`, fallback)
          )}
        </output>
      }
    >
      <LazyChartView context={context} />
    </Suspense>
  );
}

/**
 * Pass to `<DataTable displayModeRenderers={{ chart: chartRenderer }} />`
 * and list `"chart"` in `table.displayModes`.
 */
export const chartRenderer: DisplayModeRenderer = {
  View: ChartViewLoader,
  Settings: ChartSettings,
};

"use client";

import { ArrowDown, ArrowUp, GripVertical } from "lucide-react";
import { useId, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import {
  type ViewSettingField,
  ViewSettingsPanel,
} from "@/components/ui/yayaw-table/components/toolbar/view-settings-panel";
import type { DisplayModeSettingsContext } from "@/components/ui/yayaw-table/types/display-mode-renderer";
import {
  type ChartStageList,
  type ChartViewSettings,
  chartSettingFields,
  chartStageList,
} from "@/components/ui/yayaw-table/utils/chart-model";
import { cn } from "@/lib/utils";

/** A funnel's stages: drag one, or use its arrows, to change the order. */
function StageOrder({ list }: { list: ChartStageList }) {
  const id = useId();
  const root = useRef<HTMLDivElement>(null);
  const [dragged, setDragged] = useState<number>();
  const [target, setTarget] = useState<number>();
  const endDrag = () => {
    setDragged(undefined);
    setTarget(undefined);
  };
  // The moved stage keeps the focus, on the arrow that can still move it.
  const moveByKeyboard = (from: number, to: number, value: string) => {
    list.move(from, to);
    requestAnimationFrame(() => {
      const buttons = [
        ...(root.current?.querySelectorAll<HTMLButtonElement>(
          `[data-stage-move="${CSS.escape(value)}"]`
        ) ?? []),
      ];
      const preferred = to < from ? buttons.at(0) : buttons.at(1);
      (preferred?.disabled
        ? buttons.find((button) => !button.disabled)
        : preferred
      )?.focus();
    });
  };
  return (
    <div className="grid gap-1.5" data-chart-stages ref={root}>
      <p className="text-muted-foreground text-sm" id={`${id}-label`}>
        {list.label}
      </p>
      <ol aria-labelledby={`${id}-label`} className="grid gap-1">
        {list.stages.map((stage, index) => (
          // biome-ignore lint/a11y/noNoninteractiveElementInteractions: a stage is dragged and dropped with the pointer; its arrow buttons are the keyboard path.
          <li
            className={cn(
              "flex min-h-9 min-w-0 items-center gap-1 rounded-md border bg-background pr-1 pl-1.5 text-sm",
              target === index && dragged !== index && "border-primary",
              dragged === index && "opacity-50"
            )}
            data-stage={stage.value}
            draggable
            key={stage.value}
            onDragEnd={endDrag}
            onDragOver={(event) => {
              if (dragged !== undefined) {
                event.preventDefault();
                event.dataTransfer.dropEffect = "move";
                setTarget(index);
              }
            }}
            onDragStart={(event) => {
              event.dataTransfer.effectAllowed = "move";
              event.dataTransfer.setData("text/plain", stage.label);
              setDragged(index);
            }}
            onDrop={(event) => {
              event.preventDefault();
              if (dragged !== undefined && dragged !== index) {
                list.move(dragged, index);
              }
              endDrag();
            }}
          >
            <GripVertical
              aria-hidden="true"
              className="size-4 shrink-0 cursor-grab text-muted-foreground/60"
            />
            <span className="min-w-0 flex-1 truncate">{stage.label}</span>
            <Button
              aria-label={stage.moveUpLabel}
              data-stage-move={stage.value}
              disabled={index === 0}
              onClick={() => moveByKeyboard(index, index - 1, stage.value)}
              size="icon-xs"
              type="button"
              variant="ghost"
            >
              <ArrowUp aria-hidden="true" />
            </Button>
            <Button
              aria-label={stage.moveDownLabel}
              data-stage-move={stage.value}
              disabled={index === list.stages.length - 1}
              onClick={() => moveByKeyboard(index, index + 1, stage.value)}
              size="icon-xs"
              type="button"
              variant="ghost"
            >
              <ArrowDown aria-hidden="true" />
            </Button>
          </li>
        ))}
      </ol>
      <p className="text-muted-foreground text-xs">{list.hint}</p>
      {list.customized ? (
        <Button
          className="justify-self-start font-normal"
          onClick={list.reset}
          size="sm"
          type="button"
          variant="ghost"
        >
          {list.resetLabel}
        </Button>
      ) : null}
    </div>
  );
}

/** View → Card settings of the chart: type, axes, grouping and display. */
export function ChartSettings({
  context,
}: {
  context: DisplayModeSettingsContext;
}) {
  const view = context.settings as ChartViewSettings;
  const input = {
    columns: context.columns,
    defaults: context.defaults as ChartViewSettings,
    view,
    locale: context.locale,
    translate: (key: string, fallback: string) =>
      context.translate(`chart.${key}`, fallback),
    update: (next: Record<string, unknown>) => context.updateSettings(next),
  };
  const fields: ViewSettingField[] = chartSettingFields(input);
  const stages = chartStageList(input);
  return (
    <ViewSettingsPanel fields={fields}>
      {stages ? <StageOrder list={stages} /> : null}
      <Button
        className="font-normal"
        disabled={Object.keys(view).length === 0}
        onClick={() => context.updateSettings(undefined)}
        size="sm"
        type="button"
        variant="outline"
      >
        {context.translate("common.reset", "Reset")}
      </Button>
    </ViewSettingsPanel>
  );
}

"use client";

import { Table2 } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import {
  Area,
  AreaChart,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  LabelList,
  Line,
  LineChart,
  Pie,
  PieChart,
  XAxis,
  YAxis,
} from "recharts";
import { Button } from "@/components/ui/button";
import {
  type ChartConfig,
  ChartContainer,
  ChartTooltip,
} from "@/components/ui/chart";
import type { DisplayModeRenderContext } from "@/components/ui/yayaw-table/types/display-mode-renderer";
import {
  buildChartModel,
  type ChartCategory,
  type ChartDataResult,
  type ChartLabelKey,
  type ChartModel,
  type ChartSeriesItem,
  type ChartViewSettings,
  canAddChartFilters,
  chartAggregateRequest,
  chartGroupFilters,
  chartLabel,
  chartTickFormat,
  chartValueText,
  loadChartData,
  type ResolvedChartSettings,
  resolveChartSettings,
} from "@/components/ui/yayaw-table/utils/chart-model";
import { cn } from "@/lib/utils";
import { FunnelChart, FunnelDataTable } from "./chart-funnel";

/** The host's shadcn chart tokens, light and dark. */
const PALETTE = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
];
const OTHER_COLOR = "var(--muted-foreground)";
const CHART_HEIGHT = 320;
const ROW_HEIGHT = 36;
const AXIS_WIDTH = 120;

const valueDomain = (model: ChartModel): [number, number] => [
  model.valueTicks.at(0) ?? 0,
  model.valueTicks.at(-1) ?? 1,
];

type Label = (
  key: ChartLabelKey,
  params?: Record<string, number | string>
) => string;
type GroupClick = (category?: ChartCategory, series?: ChartSeriesItem) => void;

interface ChartState {
  result?: ChartDataResult;
  error?: string;
  loading: boolean;
}

/** Groups from `actions.aggregate`, or computed over the rows matching the query. */
function useChartResult(
  context: DisplayModeRenderContext,
  settings: ResolvedChartSettings
): ChartState {
  const [state, setState] = useState<ChartState>({ loading: true });
  const { aggregate, columns, list, listParams, locale, revision } = context;
  const pageRows = list ? undefined : context.rows;
  const request = useMemo(
    () => chartAggregateRequest(settings, columns),
    [columns, settings]
  );
  const requestKey = JSON.stringify(request ?? null);
  useEffect(() => {
    const parsed = JSON.parse(requestKey) as ReturnType<
      typeof chartAggregateRequest
    > | null;
    if (!parsed || revision < 0) {
      setState({ loading: false });
      return;
    }
    const controller = new AbortController();
    setState((current) => ({ ...current, loading: true }));
    loadChartData({
      aggregate: aggregate as
        | ((params: Record<string, unknown>) => unknown)
        | undefined,
      list,
      rows: pageRows,
      params: listParams,
      request: parsed,
      locale,
      signal: controller.signal,
    })
      .then((result) => setState({ result, loading: false }))
      .catch((reason: unknown) => {
        if (!controller.signal.aborted) {
          setState({
            error: reason instanceof Error ? reason.message : String(reason),
            loading: false,
          });
        }
      });
    return () => controller.abort();
  }, [aggregate, list, listParams, locale, pageRows, requestKey, revision]);
  return state;
}

/** Series keys safe as Recharts data keys and CSS names. */
const seriesKey = (index: number) => `s${index}`;
/** Recharts curve of lines and areas. */
const curveOf = (settings: ResolvedChartSettings) =>
  settings.curve === "linear" ? "linear" : "monotone";

/** One row per category; areas stacked to 100 % plot each series' share. */
function chartRows(model: ChartModel) {
  return model.categories.map((category) => {
    const row: Record<string, number | string> = {
      id: category.id,
      label: category.label,
    };
    for (const [index, item] of model.series.entries()) {
      row[seriesKey(index)] = model.percent
        ? (category.shares?.[item.id] ?? 0)
        : (category.values[item.id] ?? 0);
    }
    return row;
  });
}

/**
 * Clicking a category's band (bars, points, areas) shows its records. The
 * charts using it process pointer moves as they come (`throttledEvents`
 * empty), so a tap or a quick click reads the category under the pointer.
 */
const categoryClick =
  (model: ChartModel, onGroup: GroupClick) =>
  (state: { activeTooltipIndex?: unknown } | null) => {
    const active = state?.activeTooltipIndex;
    const index =
      active === null || active === undefined || active === ""
        ? Number.NaN
        : Number(active);
    if (Number.isInteger(index)) {
      onGroup(model.categories.at(index));
    }
  };
/** No throttled pointer events: see `categoryClick`. */
const IMMEDIATE_EVENTS: [] = [];

function chartConfig(model: ChartModel): ChartConfig {
  return Object.fromEntries(
    model.series.map((item, index) => [
      seriesKey(index),
      { label: item.label, color: item.color },
    ])
  );
}

function TooltipBody({
  active,
  label,
  model,
  payload,
}: {
  active?: boolean;
  label?: unknown;
  model: ChartModel;
  payload?: readonly {
    dataKey?: unknown;
    value?: unknown;
    payload?: Record<string, unknown>;
  }[];
}) {
  if (!(active && payload?.length)) {
    return null;
  }
  const title =
    typeof label === "string" || typeof label === "number"
      ? String(label)
      : String(payload.at(0)?.payload?.label ?? "");
  return (
    <div className="grid min-w-32 gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl">
      <div className="font-medium">{title}</div>
      {payload.map((entry) => {
        const index = Number(String(entry.dataKey ?? "s0").slice(1));
        const series = model.series.at(Number.isFinite(index) ? index : 0);
        const category = model.categories.find(
          (item) => item.id === entry.payload?.id
        );
        const color =
          model.type === "donut" || model.single
            ? (category?.color ?? series?.color)
            : series?.color;
        return (
          <div
            className="flex items-center gap-2"
            key={String(entry.dataKey ?? entry.payload?.id)}
          >
            <span
              aria-hidden="true"
              className="size-2.5 shrink-0 rounded-[2px]"
              style={{ background: color }}
            />
            <span className="text-muted-foreground">
              {model.single ? model.valueLabel : series?.label}
            </span>
            <span className="ml-auto font-medium font-mono tabular-nums">
              {category
                ? chartValueText(model, category, series)
                : model.format(Number(entry.value ?? 0))}
            </span>
          </div>
        );
      })}
    </div>
  );
}

function BarsChart({
  model,
  settings,
  onGroup,
  clickable,
}: {
  model: ChartModel;
  settings: ResolvedChartSettings;
  onGroup: GroupClick;
  clickable: boolean;
}) {
  const horizontal = model.type === "horizontalBar";
  const rows = chartRows(model);
  const stacked = model.stacked && model.series.length > 1;
  let labelPosition: "center" | "right" | "top" = "top";
  if (stacked) {
    labelPosition = "center";
  } else if (horizontal) {
    labelPosition = "right";
  }
  const height = horizontal
    ? Math.max(CHART_HEIGHT, rows.length * ROW_HEIGHT)
    : CHART_HEIGHT;
  return (
    <ChartContainer
      className="aspect-auto w-full"
      config={chartConfig(model)}
      style={{ height }}
    >
      <BarChart
        accessibilityLayer
        data={rows}
        layout={horizontal ? "vertical" : "horizontal"}
        margin={{ top: 20, right: 24, left: 8, bottom: 4 }}
      >
        <CartesianGrid horizontal={!horizontal} vertical={horizontal} />
        {horizontal ? (
          <>
            <XAxis
              axisLine={false}
              domain={valueDomain(model)}
              tickFormatter={(value: number) => model.format(value)}
              tickLine={false}
              ticks={model.valueTicks}
              type="number"
            />
            <YAxis
              axisLine={false}
              dataKey="label"
              tickLine={false}
              type="category"
              width={AXIS_WIDTH}
            />
          </>
        ) : (
          <>
            <XAxis
              axisLine={false}
              dataKey="label"
              tickLine={false}
              tickMargin={8}
            />
            <YAxis
              axisLine={false}
              domain={valueDomain(model)}
              tickFormatter={(value: number) => model.format(value)}
              tickLine={false}
              ticks={model.valueTicks}
              type="number"
              width="auto"
            />
          </>
        )}
        <ChartTooltip
          content={<TooltipBody model={model} />}
          cursor={{ fillOpacity: 0.4 }}
        />
        {model.series.map((item, index) => (
          <Bar
            className={clickable ? "cursor-pointer" : undefined}
            dataKey={seriesKey(index)}
            fill={item.color}
            isAnimationActive={false}
            key={item.id}
            maxBarSize={64}
            name={item.label}
            onClick={(_data: unknown, categoryIndex: number) =>
              onGroup(model.categories.at(categoryIndex), item)
            }
            radius={stacked ? 0 : 4}
            stackId={stacked ? "stack" : undefined}
          >
            {model.single
              ? model.categories.map((category) => (
                  <Cell fill={category.color} key={category.id} />
                ))
              : null}
            {settings.showDataLabels ? (
              <LabelList
                className="fill-foreground"
                dataKey={seriesKey(index)}
                fontSize={11}
                formatter={(value: unknown) =>
                  Number(value) ? model.format(Number(value)) : ""
                }
                position={labelPosition}
              />
            ) : null}
          </Bar>
        ))}
      </BarChart>
    </ChartContainer>
  );
}

function LinesChart({
  model,
  settings,
  onGroup,
}: {
  model: ChartModel;
  settings: ResolvedChartSettings;
  onGroup: GroupClick;
}) {
  return (
    <ChartContainer
      className="aspect-auto w-full"
      config={chartConfig(model)}
      style={{ height: CHART_HEIGHT }}
    >
      <LineChart
        accessibilityLayer
        data={chartRows(model)}
        margin={{ top: 20, right: 24, left: 8, bottom: 4 }}
        onClick={categoryClick(model, onGroup)}
        throttledEvents={IMMEDIATE_EVENTS}
      >
        <CartesianGrid vertical={false} />
        <XAxis
          axisLine={false}
          dataKey="label"
          interval={0}
          padding={{ left: 40, right: 40 }}
          tickLine={false}
          tickMargin={8}
        />
        <YAxis
          axisLine={false}
          domain={valueDomain(model)}
          tickFormatter={(value: number) => model.format(value)}
          tickLine={false}
          ticks={model.valueTicks}
          type="number"
          width="auto"
        />
        <ChartTooltip content={<TooltipBody model={model} />} />
        {model.series.map((item, index) => (
          <Line
            activeDot={{ r: 6, className: "cursor-pointer" }}
            dataKey={seriesKey(index)}
            dot={{ r: 3, fill: item.color }}
            isAnimationActive={false}
            key={item.id}
            name={item.label}
            stroke={item.color}
            strokeWidth={2}
            type={curveOf(settings)}
          >
            {settings.showDataLabels ? (
              <LabelList
                className="fill-foreground"
                dataKey={seriesKey(index)}
                fontSize={11}
                formatter={(value: unknown) => model.format(Number(value))}
                offset={10}
                position="top"
              />
            ) : null}
          </Line>
        ))}
      </LineChart>
    </ChartContainer>
  );
}

/** Areas: one per series, stacked (as values or shares of 100 %) or overlapping. */
function AreasChart({
  model,
  settings,
  onGroup,
}: {
  model: ChartModel;
  settings: ResolvedChartSettings;
  onGroup: GroupClick;
}) {
  const stacked = model.stacked && !model.single;
  const tickFormat = chartTickFormat(model);
  return (
    <ChartContainer
      className="aspect-auto w-full"
      config={chartConfig(model)}
      style={{ height: CHART_HEIGHT }}
    >
      <AreaChart
        accessibilityLayer
        data={chartRows(model)}
        margin={{ top: 20, right: 24, left: 8, bottom: 4 }}
        onClick={categoryClick(model, onGroup)}
        throttledEvents={IMMEDIATE_EVENTS}
      >
        <CartesianGrid vertical={false} />
        {/* Labels that would overlap on narrow charts are skipped. */}
        <XAxis
          axisLine={false}
          dataKey="label"
          padding={{ left: 40, right: 40 }}
          tickLine={false}
          tickMargin={8}
        />
        <YAxis
          axisLine={false}
          domain={valueDomain(model)}
          tickFormatter={(value: number) => tickFormat(value)}
          tickLine={false}
          ticks={model.valueTicks}
          type="number"
          width="auto"
        />
        <ChartTooltip content={<TooltipBody model={model} />} />
        {model.series.map((item, index) => (
          <Area
            activeDot={{ r: 5, className: "cursor-pointer" }}
            dataKey={seriesKey(index)}
            fill={item.color}
            fillOpacity={stacked ? 0.6 : 0.3}
            isAnimationActive={false}
            key={item.id}
            name={item.label}
            stackId={stacked ? "stack" : undefined}
            stroke={item.color}
            strokeWidth={2}
            type={curveOf(settings)}
          >
            {settings.showDataLabels ? (
              <LabelList
                className="fill-foreground"
                dataKey={seriesKey(index)}
                fontSize={11}
                formatter={(value: unknown) =>
                  Number(value) ? tickFormat(Number(value)) : ""
                }
                offset={8}
                position="top"
              />
            ) : null}
          </Area>
        ))}
      </AreaChart>
    </ChartContainer>
  );
}

/** Bars for one metric and a line for another, on a second axis when their units differ. */
function ComboChart({
  model,
  settings,
  onGroup,
  clickable,
}: {
  model: ChartModel;
  settings: ResolvedChartSettings;
  onGroup: GroupClick;
  clickable: boolean;
}) {
  const [bars, line] = model.series;
  const right = model.secondaryTicks;
  const lineAxis = right ? "right" : "left";
  const barFormat = bars?.format ?? model.format;
  const lineFormat = line?.format ?? model.format;
  return (
    <ChartContainer
      className="aspect-auto w-full"
      config={chartConfig(model)}
      style={{ height: CHART_HEIGHT }}
    >
      <ComposedChart
        accessibilityLayer
        data={chartRows(model)}
        margin={{ top: 20, right: right ? 8 : 24, left: 8, bottom: 4 }}
        onClick={categoryClick(model, onGroup)}
        throttledEvents={IMMEDIATE_EVENTS}
      >
        <CartesianGrid vertical={false} />
        <XAxis
          axisLine={false}
          dataKey="label"
          tickLine={false}
          tickMargin={8}
        />
        <YAxis
          axisLine={false}
          domain={valueDomain(model)}
          tickFormatter={(value: number) => barFormat(value)}
          tickLine={false}
          ticks={model.valueTicks}
          type="number"
          width="auto"
          yAxisId="left"
        />
        {right ? (
          <YAxis
            axisLine={false}
            domain={[right.at(0) ?? 0, right.at(-1) ?? 1]}
            orientation="right"
            tickFormatter={(value: number) => lineFormat(value)}
            tickLine={false}
            ticks={right}
            type="number"
            width="auto"
            yAxisId="right"
          />
        ) : null}
        <ChartTooltip
          content={<TooltipBody model={model} />}
          cursor={{ fillOpacity: 0.4 }}
        />
        {bars ? (
          <Bar
            className={clickable ? "cursor-pointer" : undefined}
            dataKey={seriesKey(0)}
            fill={bars.color}
            isAnimationActive={false}
            maxBarSize={64}
            name={bars.label}
            radius={4}
            yAxisId="left"
          >
            {settings.showDataLabels ? (
              <LabelList
                className="fill-foreground"
                dataKey={seriesKey(0)}
                fontSize={11}
                formatter={(value: unknown) =>
                  Number(value) ? barFormat(Number(value)) : ""
                }
                position="top"
              />
            ) : null}
          </Bar>
        ) : null}
        {line ? (
          <Line
            activeDot={{ r: 6, className: "cursor-pointer" }}
            dataKey={seriesKey(1)}
            dot={{ r: 3, fill: line.color }}
            isAnimationActive={false}
            name={line.label}
            stroke={line.color}
            strokeWidth={2}
            type={curveOf(settings)}
            yAxisId={lineAxis}
          >
            {settings.showDataLabels ? (
              <LabelList
                className="fill-foreground"
                dataKey={seriesKey(1)}
                fontSize={11}
                formatter={(value: unknown) => lineFormat(Number(value))}
                offset={10}
                position="top"
              />
            ) : null}
          </Line>
        ) : null}
      </ComposedChart>
    </ChartContainer>
  );
}

function DonutChart({
  model,
  onGroup,
  clickable,
  label,
}: {
  model: ChartModel;
  onGroup: GroupClick;
  clickable: boolean;
  label: Label;
}) {
  const data = model.categories
    .filter((category) => category.total > 0)
    .map((category) => ({
      id: category.id,
      label: category.label,
      value: category.total,
    }));
  return (
    <ChartContainer
      className="aspect-auto w-full"
      config={chartConfig(model)}
      style={{ height: CHART_HEIGHT }}
    >
      <PieChart accessibilityLayer>
        <ChartTooltip content={<TooltipBody model={model} />} />
        <Pie
          className={clickable ? "cursor-pointer" : undefined}
          data={data}
          dataKey="value"
          innerRadius="55%"
          isAnimationActive={false}
          nameKey="label"
          onClick={(_data: unknown, index: number) =>
            onGroup(
              model.categories.find(
                (category) => category.id === data.at(index)?.id
              )
            )
          }
          outerRadius="80%"
          strokeWidth={2}
        >
          {data.map((item) => (
            <Cell
              fill={
                model.categories.find((category) => category.id === item.id)
                  ?.color
              }
              key={item.id}
              stroke="var(--background)"
            />
          ))}
        </Pie>
        <text
          className="fill-foreground font-semibold text-2xl"
          dominantBaseline="middle"
          textAnchor="middle"
          x="50%"
          y="48%"
        >
          {model.format(model.total)}
        </text>
        <text
          className="fill-muted-foreground text-xs"
          dominantBaseline="middle"
          textAnchor="middle"
          x="50%"
          y="56%"
        >
          {label("total")}
        </text>
      </PieChart>
    </ChartContainer>
  );
}

function NumberChart({ model }: { model: ChartModel }) {
  return (
    <div className="grid place-items-center gap-1 py-12 text-center">
      <output
        className="font-semibold text-5xl tabular-nums tracking-tight"
        data-chart-number
      >
        {model.format(model.total)}
      </output>
      <span className="text-muted-foreground text-sm">{model.valueLabel}</span>
    </div>
  );
}

function ChartLegend({
  model,
  settings,
}: {
  model: ChartModel;
  settings: ResolvedChartSettings;
}) {
  let items: { id: string; label: string; color: string; value?: number }[] =
    model.series.map((item) => ({ ...item, value: undefined }));
  if (model.type === "donut") {
    items = model.categories
      .filter((category) => category.total > 0)
      .map((category) => ({ ...category, value: category.total }));
  } else if (model.type === "funnel") {
    items = model.stages ?? [];
  }
  return (
    <ul
      className="flex flex-wrap items-center justify-center gap-x-4 gap-y-1 text-xs"
      data-chart-legend
    >
      {items.map((item) => (
        <li className="flex items-center gap-1.5" key={item.id}>
          <span
            aria-hidden="true"
            className="size-2.5 shrink-0 rounded-[2px]"
            style={{ background: item.color }}
          />
          <span>{item.label}</span>
          {settings.showDataLabels && item.value !== undefined ? (
            <span className="text-muted-foreground tabular-nums">
              {model.format(item.value)}
            </span>
          ) : null}
        </li>
      ))}
    </ul>
  );
}

/** The chart's numbers as a table; each group opens its records. */
function ChartDataTable({
  model,
  onGroup,
  clickable,
  label,
}: {
  model: ChartModel;
  onGroup: GroupClick;
  clickable: boolean;
  label: Label;
}) {
  const withSeries = !model.single;
  return (
    <div className="overflow-x-auto rounded-md border">
      <table className="w-full text-sm" data-chart-table>
        <caption className="sr-only">{model.title}</caption>
        <thead className="bg-muted/50 text-left text-muted-foreground">
          <tr>
            <th className="px-3 py-2 font-medium" scope="col">
              {model.xLabel || label("group")}
            </th>
            {model.series.map((item) => (
              <th
                className="px-3 py-2 text-right font-medium"
                key={item.id}
                scope="col"
              >
                {withSeries ? item.label : model.valueLabel}
              </th>
            ))}
            {model.totalColumn ? (
              <th className="px-3 py-2 text-right font-medium" scope="col">
                {label("total")}
              </th>
            ) : null}
          </tr>
        </thead>
        <tbody>
          {model.categories.map((category) => (
            <tr className="border-t" key={category.id}>
              <th className="px-3 py-1.5 text-left font-normal" scope="row">
                {clickable && !category.other ? (
                  <Button
                    aria-label={label("showRecords", { group: category.label })}
                    className="h-auto px-0 py-0 font-normal"
                    onClick={() => onGroup(category)}
                    type="button"
                    variant="link"
                  >
                    {category.label}
                  </Button>
                ) : (
                  category.label
                )}
              </th>
              {model.series.map((item) => (
                <td
                  className="px-3 py-1.5 text-right tabular-nums"
                  key={item.id}
                >
                  {chartValueText(model, category, item)}
                </td>
              ))}
              {model.totalColumn ? (
                <td className="px-3 py-1.5 text-right font-medium tabular-nums">
                  {model.format(category.total)}
                </td>
              ) : null}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function ChartBody({
  model,
  settings,
  onGroup,
  clickable,
  label,
}: {
  model: ChartModel;
  settings: ResolvedChartSettings;
  onGroup: GroupClick;
  clickable: boolean;
  label: Label;
}) {
  switch (model.type) {
    case "number":
      return <NumberChart model={model} />;
    case "donut":
      return (
        <DonutChart
          clickable={clickable}
          label={label}
          model={model}
          onGroup={onGroup}
        />
      );
    case "line":
      return <LinesChart model={model} onGroup={onGroup} settings={settings} />;
    case "area":
      return <AreasChart model={model} onGroup={onGroup} settings={settings} />;
    case "combo":
      return (
        <ComboChart
          clickable={clickable}
          model={model}
          onGroup={onGroup}
          settings={settings}
        />
      );
    case "funnel":
      return (
        <FunnelChart
          clickable={clickable}
          label={label}
          model={model}
          onGroup={onGroup}
        />
      );
    default:
      return (
        <BarsChart
          clickable={clickable}
          model={model}
          onGroup={onGroup}
          settings={settings}
        />
      );
  }
}

function ChartMessage({
  children,
  alert,
}: {
  children: string;
  alert?: boolean;
}) {
  return alert ? (
    <div className="text-destructive text-sm" role="alert">
      {children}
    </div>
  ) : (
    <output className="block text-muted-foreground text-sm">{children}</output>
  );
}

/** Chart, or its table fallback, with the legend and the click hint. */
function ChartContent({
  model,
  settings,
  asTable,
  clickable,
  loading,
  onGroup,
  label,
}: {
  model: ChartModel;
  settings: ResolvedChartSettings;
  asTable: boolean;
  clickable: boolean;
  loading: boolean;
  onGroup: GroupClick;
  label: Label;
}) {
  const hasTable = model.type !== "number";
  const funnel = model.type === "funnel";
  const showLegend =
    settings.showLegend &&
    !asTable &&
    (model.type === "donut" || funnel || (hasTable && !model.single));
  let hint: ChartLabelKey = "filterUnavailable";
  if (clickable) {
    hint = funnel ? "funnelHint" : "filterHint";
  }
  const Table = funnel ? FunnelDataTable : ChartDataTable;
  return (
    <div className={cn("grid gap-3", loading && "opacity-60")}>
      {asTable && hasTable ? (
        <Table
          clickable={clickable}
          label={label}
          model={model}
          onGroup={onGroup}
        />
      ) : (
        <ChartBody
          clickable={clickable}
          label={label}
          model={model}
          onGroup={onGroup}
          settings={settings}
        />
      )}
      {showLegend ? <ChartLegend model={model} settings={settings} /> : null}
      {hasTable && !asTable ? (
        <p className="text-muted-foreground text-xs" data-chart-hint>
          {label(hint)}
        </p>
      ) : null}
    </div>
  );
}

function ChartHeader({
  title,
  asTable,
  onToggle,
  label,
}: {
  title?: string;
  /** Undefined when the chart has no table fallback (number charts). */
  asTable?: boolean;
  onToggle: () => void;
  label: Label;
}) {
  return (
    <div className="flex flex-wrap items-center justify-between gap-2">
      <h3 className="font-medium text-sm" data-chart-title>
        {title}
      </h3>
      {asTable === undefined ? null : (
        <Button
          aria-pressed={asTable}
          className="h-8 font-normal text-xs"
          onClick={onToggle}
          size="sm"
          type="button"
          variant="outline"
        >
          <Table2 aria-hidden="true" className="size-4" />
          {label(asTable ? "showChart" : "showTable")}
        </Button>
      )}
    </div>
  );
}

/** Loading, error, partial and empty states above the chart. */
function ChartMessages({
  state,
  model,
  notice,
  label,
}: {
  state: ChartState;
  model?: ChartModel;
  notice?: string;
  label: Label;
}) {
  const messages: { key: string; text: string; alert?: boolean }[] = [];
  if (state.error) {
    messages.push({ key: "error", text: state.error, alert: true });
  }
  if (notice) {
    messages.push({ key: "notice", text: notice, alert: true });
  }
  if (state.result?.truncated) {
    messages.push({ key: "truncated", text: label("truncated") });
  }
  if (!model && state.loading) {
    messages.push({ key: "loading", text: label("loading") });
  }
  if (model?.empty && model.type !== "number") {
    messages.push({ key: "empty", text: label("empty") });
  }
  return (
    <>
      {messages.map((message) => (
        <ChartMessage alert={message.alert} key={message.key}>
          {message.text}
        </ChartMessage>
      ))}
    </>
  );
}

/** Chart display mode for YaYaw Table, rendered with shadcn/ui charts (Recharts). */
export function ChartView({ context }: { context: DisplayModeRenderContext }) {
  const { columns, locale, coloredTags, translate } = context;
  const label: Label = (key, params) =>
    chartLabel(
      key,
      locale,
      (name, fallback) => translate(`chart.${name}`, fallback),
      params
    );
  const settings = useMemo(
    () =>
      resolveChartSettings(
        columns,
        context.defaults as ChartViewSettings,
        context.settings as ChartViewSettings
      ),
    [columns, context.defaults, context.settings]
  );
  const state = useChartResult(context, settings);
  const [asTable, setAsTable] = useState(false);
  const [notice, setNotice] = useState<string>();
  const { result } = state;
  const model = useMemo(
    () =>
      result
        ? buildChartModel({
            result,
            settings,
            columns,
            locale,
            translate: (name, fallback) => translate(`chart.${name}`, fallback),
            palette: PALETTE,
            otherColor: OTHER_COLOR,
            coloredTags,
          })
        : undefined,
    [coloredTags, columns, locale, result, settings, translate]
  );
  const clickable =
    settings.type !== "number" && canAddChartFilters(context.advancedFilters);
  const onGroup: GroupClick = (category, series) => {
    const rules = chartGroupFilters(settings, columns, { category, series });
    if (
      rules &&
      !context.showRecords(rules as unknown as Record<string, unknown>[])
    ) {
      setNotice(label("filterUnavailable"));
    }
  };

  if (!(settings.xColumn || settings.type === "number")) {
    return <ChartMessage>{label("noColumn")}</ChartMessage>;
  }
  const visible = model && !(model.empty && model.type !== "number");
  return (
    <section
      aria-busy={state.loading}
      aria-label={model?.title}
      className="grid gap-3"
      data-chart-type={settings.type}
    >
      <ChartHeader
        asTable={model && model.type !== "number" ? asTable : undefined}
        label={label}
        onToggle={() => setAsTable((current) => !current)}
        title={model?.title}
      />
      <ChartMessages
        label={label}
        model={model}
        notice={notice}
        state={state}
      />
      {visible ? (
        <ChartContent
          asTable={asTable}
          clickable={clickable}
          label={label}
          loading={state.loading}
          model={model}
          onGroup={onGroup}
          settings={settings}
        />
      ) : null}
    </section>
  );
}
